#include "oblivion/analyzer.hpp"
#include <Windows.h>
#include <filesystem>
#include <sstream>
#include <system_error>
namespace oblivion { namespace {
void warn(file_analysis&r,std::wstring s){if(r.warnings.size()<64)r.warnings.push_back(std::move(s));}
void merge(file_analysis&a,const file_analysis&b){a.files+=b.files;a.directories+=b.directories;a.logical_bytes+=b.logical_bytes;a.alternate_streams+=b.alternate_streams;a.alternate_stream_bytes+=b.alternate_stream_bytes;a.reparse_points+=b.reparse_points;a.hardlinked_files+=b.hardlinked_files;a.sparse_files+=b.sparse_files;a.compressed_files+=b.compressed_files;a.encrypted_files+=b.encrypted_files;a.readonly_entries+=b.readonly_entries;a.inaccessible_entries+=b.inaccessible_entries;for(const auto&w:b.warnings)warn(a,w);}
void streams(const std::filesystem::path&p,file_analysis&r){WIN32_FIND_STREAM_DATA d{};HANDLE h=FindFirstStreamW(p.c_str(),FindStreamInfoStandard,&d,0);if(h==INVALID_HANDLE_VALUE)return;do{std::wstring n=d.cStreamName;if(!n.empty()&&n!=L"::$DATA"){++r.alternate_streams;if(d.StreamSize.QuadPart>0)r.alternate_stream_bytes+=static_cast<std::uint64_t>(d.StreamSize.QuadPart);}}while(FindNextStreamW(h,&d));FindClose(h);}
void scan(const std::filesystem::path&p,file_analysis&r){DWORD a=GetFileAttributesW(p.c_str());if(a==INVALID_FILE_ATTRIBUTES){++r.inaccessible_entries;warn(r,L"Nicht zugreifbar: "+p.wstring());return;} if(a&FILE_ATTRIBUTE_READONLY)++r.readonly_entries;if(a&FILE_ATTRIBUTE_REPARSE_POINT){++r.reparse_points;if(a&FILE_ATTRIBUTE_DIRECTORY)++r.directories;else ++r.files;return;}if(!(a&FILE_ATTRIBUTE_DIRECTORY)){++r.files;WIN32_FILE_ATTRIBUTE_DATA fd{};if(GetFileAttributesExW(p.c_str(),GetFileExInfoStandard,&fd)){ULARGE_INTEGER s{};s.HighPart=fd.nFileSizeHigh;s.LowPart=fd.nFileSizeLow;r.logical_bytes+=s.QuadPart;}else ++r.inaccessible_entries;if(a&FILE_ATTRIBUTE_SPARSE_FILE)++r.sparse_files;if(a&FILE_ATTRIBUTE_COMPRESSED)++r.compressed_files;if(a&FILE_ATTRIBUTE_ENCRYPTED)++r.encrypted_files;HANDLE h=CreateFileW(p.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr);if(h!=INVALID_HANDLE_VALUE){BY_HANDLE_FILE_INFORMATION i{};if(GetFileInformationByHandle(h,&i)&&i.nNumberOfLinks>1)++r.hardlinked_files;CloseHandle(h);}else ++r.inaccessible_entries;streams(p,r);return;}++r.directories;std::error_code ec;std::filesystem::directory_iterator it(p,ec),end;if(ec){++r.inaccessible_entries;warn(r,L"Verzeichnis nicht lesbar: "+p.wstring());return;}while(it!=end){scan(it->path(),r);it.increment(ec);if(ec){++r.inaccessible_entries;warn(r,L"Verzeichnis unvollständig aufgezählt: "+p.wstring());break;}}}
std::wstring bytes(std::uint64_t v){wchar_t b[64]{};const double x=static_cast<double>(v);if(x>=1099511627776.0)swprintf_s(b,L"%.2f TiB",x/1099511627776.0);else if(x>=1073741824.0)swprintf_s(b,L"%.2f GiB",x/1073741824.0);else if(x>=1048576.0)swprintf_s(b,L"%.2f MiB",x/1048576.0);else if(x>=1024.0)swprintf_s(b,L"%.2f KiB",x/1024.0);else swprintf_s(b,L"%llu B",static_cast<unsigned long long>(v));return b;}
}
file_analysis analyzer::analyze(const std::filesystem::path&p)const{file_analysis r;scan(p,r);return r;} file_analysis analyzer::analyze(const std::vector<std::filesystem::path>&ps)const{file_analysis r;for(const auto&p:ps)merge(r,analyze(p));return r;}
std::wstring format_analysis_report(const file_analysis&r,const storage_info*s){std::wostringstream o;o<<L"OBLIVION ANALYSE\n\nDateien: "<<r.files<<L"\nVerzeichnisse: "<<r.directories<<L"\nLogische Datenmenge: "<<bytes(r.logical_bytes)<<L"\nAlternate Data Streams: "<<r.alternate_streams<<L" ("<<bytes(r.alternate_stream_bytes)<<L")\nReparse Points: "<<r.reparse_points<<L"\nHardlink-Dateien: "<<r.hardlinked_files<<L"\nSparse: "<<r.sparse_files<<L"\nKomprimiert: "<<r.compressed_files<<L"\nEFS: "<<r.encrypted_files<<L"\nRead-only: "<<r.readonly_entries<<L"\nNicht vollständig zugreifbar: "<<r.inaccessible_entries<<L"\n";if(s)o<<L"\nVolume: "<<s->volume_root<<L"\nDateisystem: "<<s->filesystem<<L"\nGerät: "<<s->device_model<<L"\nBus: "<<s->bus_type<<L"\nTRIM: "<<(s->trim_enabled?L"aktiv":L"nicht erkannt")<<L"\nUSN: "<<(s->usn_journal_active?L"aktiv":L"nicht erkannt")<<L"\n";for(const auto&w:r.warnings)o<<L"- "<<w<<L"\n";return o.str();}
}
